void W3dUtilityClass::Convert_Shader(const W3dShaderStruct &shader, ShaderClass *set)
{
	set->Set_Field(ShaderClass::MASK_DEPTHCOMPARE, ShaderClass::SHIFT_DEPTHCOMPARE, shader.DepthCompare);
	set->Set_Field(ShaderClass::MASK_DEPTHMASK, ShaderClass::SHIFT_DEPTHMASK, shader.DepthMask);
	set->Set_Field(ShaderClass::MASK_COLORMASK, ShaderClass::SHIFT_COLORMASK, ShaderClass::COLOR_WRITE_ENABLE);
	set->Set_Field(ShaderClass::MASK_DSTBLEND, ShaderClass::SHIFT_DSTBLEND, shader.DestBlend);
	set->Set_Field(ShaderClass::MASK_FOG, ShaderClass::SHIFT_FOG, ShaderClass::FOG_DISABLE);
	set->Set_Field(ShaderClass::MASK_PRIGRADIENT, ShaderClass::SHIFT_PRIGRADIENT, shader.PriGradient);
	set->Set_Field(ShaderClass::MASK_SECGRADIENT, ShaderClass::SHIFT_SECGRADIENT, shader.SecGradient);
	set->Set_Field(ShaderClass::MASK_SRCBLEND, ShaderClass::SHIFT_SRCBLEND, shader.SrcBlend);
	set->Set_Field(ShaderClass::MASK_TEXTURING, ShaderClass::SHIFT_TEXTURING, shader.Texturing);
	set->Set_Field(ShaderClass::MASK_ALPHATEST, ShaderClass::SHIFT_ALPHATEST, shader.AlphaTest);
	set->Set_Field(ShaderClass::MASK_POSTDETAILCOLORFUNC, ShaderClass::SHIFT_POSTDETAILCOLORFUNC, shader.DetailColorFunc);
	set->Set_Field(ShaderClass::MASK_POSTDETAILALPHAFUNC, ShaderClass::SHIFT_POSTDETAILALPHAFUNC, shader.DetailAlphaFunc);
}

